/* From Uiverse.io by Bodyhc  - Tags:  */
.__UIV_SCOPE__ .ag-courses_item {
  margin: auto;
  overflow: hidden;
  border-radius: 28px;
}
.__UIV_SCOPE__ .ag-courses-item_link {
  display: block;
  padding: 30px 20px;
  background-color: #121212;
  overflow: hidden;
  position: relative;
  text-decoration: none;
}

.__UIV_SCOPE__ .ag-courses-item_link:hover,
.__UIV_SCOPE__ .ag-courses-item_link:hover .ag-courses-item_date {
  color: #121212;
}
.__UIV_SCOPE__ .ag-courses-item_link:hover .ag-courses-item_bg {
  -webkit-transform: scale(10);
  -ms-transform: scale(10);
  transform: scale(10);
}
.__UIV_SCOPE__ .ag-courses-item_title {
  min-height: 57px;
  margin: 0 0 30px;
  overflow: hidden;
  font-weight: bold;
  font-size: 20px;
  color: rgb(255, 255, 255);
  z-index: 2;
  position: relative;
}
.__UIV_SCOPE__ .ag-courses-item_date-box {
  font-size: 18px;
  color: #fff;
  z-index: 2;
  position: relative;
}
.__UIV_SCOPE__ .ag-courses-item_date {
  font-weight: bold;
  color: #f9e534;
  -webkit-transition: color 0.5s ease;
  -o-transition: color 0.5s ease;
  transition: color 0.5s ease;
}
.__UIV_SCOPE__ .ag-courses-item_bg {
  height: 130px;
  width: 100px;
  background-color: #f9b234;
  z-index: 1;
  position: absolute;
  top: -75px;
  right: -75px;
  border-radius: 50%;
  -webkit-transition: all 0.5s ease;
  -o-transition: all 0.5s ease;
  transition: all 0.5s ease;
}
